#!/bin/sh
# The marine is now generated by K12 (tools/assets/k12-hero). This script keeps the K10 arsenal and
# delegates the marine so it can never overwrite marine.glb with the first-generation body.
set -eu
cd "$(dirname "$0")/../../.."
blender -b -P tools/assets/k10-marine/weapons.py
sh tools/assets/k12-hero/rebuild.sh
